import copy

def deep_merge(dict_a: dict, dict_b: dict) -> dict:
    if not isinstance(dict_a, dict) or not isinstance(dict_b, dict):
        raise TypeError("Ambos argumentos deben ser diccionarios")

    result = copy.deepcopy(dict_a)
    for k, v in dict_b.items():
        if k in result:
            if isinstance(result[k], dict) and isinstance(v, dict):
                result[k] = deep_merge(result[k], v)
            elif isinstance(result[k], list) and isinstance(v, list):
                result[k] = result[k] + copy.deepcopy(v)
            else:
                result[k] = copy.deepcopy(v)
        else:
            result[k] = copy.deepcopy(v)
    return result

