        a = {'x': {'y': 1, 'z': 2}, 'shared': 10}
        b = {'x': {'z': 3, 'w': 4}, 'shared': 20, 'extra': True}
        res = deep_merge(a, b)
        self.assertEqual(res, {'x': {'y': 1, 'z': 3, 'w': 4}, 'shared': 20, 'extra': True})

