        a = {'sub': {'v': 1}, 'arr': [10]}
        b = {'sub': {'v': 2}, 'arr': [20]}
        res = deep_merge(a, b)
        res['sub']['v'] = 999
        res['arr'].append(999)
        self.assertEqual(a, {'sub': {'v': 1}, 'arr': [10]})
        self.assertEqual(b, {'sub': {'v': 2}, 'arr': [20]})

    def test_invalid_types(self):
        with self.assertRaises(TypeError):
            deep_merge([], {})
        with self.assertRaises(TypeError):
            deep_merge({}, None)
        with self.assertRaises(TypeError):
