import functools

def retry_call(max_attempts=3, exceptions=(Exception,)):
    if max_attempts < 1:
        raise ValueError("max_attempts must be at least 1")
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last_err = None
            for _ in range(max_attempts):
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    last_err = e
            if last_err is not None:
                raise last_err
        return wrapper
    return decorator

