import unittest

class TestRetryDecorator(unittest.TestCase):
    def test_immediate_success(self):
        @retry_call(max_attempts=3)
        def add(a, b):
            """Docstring de add"""
            return a + b
        self.assertEqual(add(2, 3), 5)
        self.assertEqual(add.__name__, "add")
        self.assertEqual(add.__doc__, "Docstring de add")

    def test_retry_success(self):
        calls = [0]
        @retry_call(max_attempts=3, exceptions=(ValueError,))
        def flaky():
            calls[0] += 1
            if calls[0] < 3:
                raise ValueError("Transient error")
            return "ok"
        self.assertEqual(flaky(), "ok")
        self.assertEqual(calls[0], 3)

    def test_reraise_on_exhaustion(self):
        calls = [0]
        @retry_call(max_attempts=2, exceptions=(KeyError,))
        def always_fails():
            calls[0] += 1
            raise KeyError("Always missing")
        with self.assertRaises(KeyError):
            always_fails()
        self.assertEqual(calls[0], 2)

    def test_unhandled_exception_raises_immediately(self):
        calls = [0]
        @retry_call(max_attempts=5, exceptions=(ValueError,))
        def raises_type_error():
            calls[0] += 1
            raise TypeError("Wrong type")
        with self.assertRaises(TypeError):
            raises_type_error()
        self.assertEqual(calls[0], 1)

    def test_invalid_max_attempts(self):
        with self.assertRaises(ValueError):
            retry_call(max_attempts=0)

