import asyncio

async def run_with_deadline(coros: list, timeout: float) -> list:
    if not coros:
        return []
    if timeout <= 0:
        raise ValueError("Timeout must be positive")

    tasks = [asyncio.create_task(c) for c in coros]
    try:
        done, pending = await asyncio.wait(
            tasks,
            timeout=timeout,
            return_when=asyncio.FIRST_EXCEPTION
        )

        for t in done:
            if not t.cancelled() and t.exception() is not None:
                for p in pending:
                    p.cancel()
                if pending:
                    await asyncio.gather(*pending, return_exceptions=True)
                raise t.exception()

        if pending:
            for p in pending:
                p.cancel()
            await asyncio.gather(*pending, return_exceptions=True)
            raise asyncio.TimeoutError("Tasks exceeded deadline")

        return [t.result() for t in tasks]
    except Exception:
        for t in tasks:
            if not t.done():
                t.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        raise

class CircularBuffer:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.capacity = capacity
        self.buffer = [None] * capacity
        self.head = 0
        self.tail = 0
        self.count = 0

    def append(self, item):
        if self.count == self.capacity:
            self.buffer[self.tail] = item
            self.tail = (self.tail + 1) % self.capacity
            self.head = (self.head + 1) % self.capacity
        else:
            self.buffer[self.tail] = item
            self.tail = (self.tail + 1) % self.capacity
            self.count += 1

    def pop_oldest(self):
        if self.count == 0:
            raise IndexError("Buffer is empty")
        item = self.buffer[self.head]
        self.buffer[self.head] = None
        self.head = (self.head + 1) % self.capacity
        self.count -= 1
        return item

    def __len__(self) -> int:
        return self.count

    def is_empty(self) -> bool:
        return self.count == 0

    def is_full(self) -> bool:
        return self.count == self.capacity

    def to_list(self) -> list:
        res = []
        for i in range(self.count):
            idx = (self.head + i) % self.capacity
            res.append(self.buffer[idx])
        return res

def resolve_dependencies(tasks: dict[str, list[str]]) -> list[str]:
    if not isinstance(tasks, dict):
        raise TypeError("Invalid tasks dictionary type")

    for task, deps in tasks.items():
        if not isinstance(task, str) or not isinstance(deps, list):
            raise TypeError("Invalid tasks dictionary type")
        for dep in deps:
            if not isinstance(dep, str):
                raise TypeError("Invalid tasks dictionary type")
            if dep not in tasks:
                raise KeyError(f"Prerequisite '{dep}' is not registered in tasks")

    state = {t: 0 for t in tasks}  # 0: unvisited, 1: visiting, 2: visited
    result = []

    def dfs(t):
        if state[t] == 1:
            raise ValueError("Circular dependency detected")
        if state[t] == 2:
            return
        state[t] = 1
        for dep in sorted(tasks[t]):
            dfs(dep)
        state[t] = 2
        result.append(t)

    for task in sorted(tasks.keys()):
        if state[task] == 0:
            dfs(task)

    return result

