import unittest

class TestResolveDependencies(unittest.TestCase):
    def test_linear_and_branching_dependencies(self):
        graph = {
            'deploy': ['build', 'test'],
            'build': ['compile'],
            'compile': [],
            'test': ['build']
        }
        res = resolve_dependencies(graph)
        self.assertLess(res.index('compile'), res.index('build'))
        self.assertLess(res.index('build'), res.index('test'))
        self.assertLess(res.index('test'), res.index('deploy'))

    def test_independent_tasks_deterministic(self):
        graph = {'charlie': [], 'alpha': [], 'bravo': []}
        self.assertEqual(resolve_dependencies(graph), ['alpha', 'bravo', 'charlie'])

    def test_empty_graph(self):
        self.assertEqual(resolve_dependencies({}), [])

    def test_direct_cycle_raises_valueerror(self):
        graph = {'a': ['b'], 'b': ['a']}
        with self.assertRaises(ValueError):
            resolve_dependencies(graph)

    def test_indirect_cycle_raises_valueerror(self):
        graph = {'a': ['b'], 'b': ['c'], 'c': ['a']}
        with self.assertRaises(ValueError):
            resolve_dependencies(graph)

    def test_missing_prerequisite_raises_keyerror(self):
        graph = {'build': ['missing_task']}
        with self.assertRaises(KeyError):
            resolve_dependencies(graph)

    def test_invalid_type_raises_typeerror(self):
        with self.assertRaises(TypeError):
            resolve_dependencies("not a dict")
        with self.assertRaises(TypeError):
            resolve_dependencies({'a': "not a list"})
